const hours=(n:number)=>{const m=Math.round((n||0)*60);return `${Math.floor(m/60)} h${m%60?` ${m%60} min`:""}`};
const isExtraordinaryDate=(date:string,holidayName="")=>{const day=new Date(`${date}T12:00:00`).getDay();return Boolean(holidayName)||day===0||day===6};
