        <div className="staff-photo-frame">{member.photoData?<img src={member.photoData} alt={`Fotografía de ${member.name}`}/>:<span>{member.name.split(" ").slice(0,2).map(part=>part[0]).join("")}</span>}<label title="Subir o cambiar fotografía">＋<input type="file" accept="image/png,image/jpeg,image/webp" onChange={event=>onPhoto(member,event.target.files?.[0])}/></label></div>
